-- Passage rg12-theme-summary-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('b5945d61-2ba0-5c29-8d89-fade7d73d655', 'rg12-theme-summary-p06', (select id from public.skills where slug = 'read-g12-theme-summary'), null,
        '9-12', $q$Cranes, Late March$q$, $q$Every spring my grandmother drove me to the river
to watch the cranes come down out of a gray sky,
thousands of them, calling in voices like wooden rattles.
They stop here a few weeks to eat and rest, she told me.
Then they go north to places she would never see.

I used to think they were leaving us.
Now I know the river is not their home,
and neither is the north.
Their home is the whole long road between,
and every field along it that holds them for a while.

This year I am the one leaving,
for a school eight hundred miles away,
with a duffel bag and a list of things I will forget.
My grandmother does not drive anymore, so I drove her.
We sat in the cold with a thermos of tea between us
while the birds dropped onto the sandbars, one after another,
as if the sky were slowly emptying its pockets.

She did not tell me to come back.
She said the cranes return to the same bend of river
because their parents brought them here first,
and the young ones learn the way by flying it.

When the light went, we stayed a little longer,
listening to the calling we could no longer see.
I understood then that a place can belong to you
without keeping you,
and that she had been teaching me the route all along.$q$, 'draft')
