  ('6b1e5169-13dd-5f89-89ee-def5047adcc3', null, (select id from public.skills where slug = 'read-g12-theme-summary'), null, 'hard',
   $q$How does the structure of Esperanza's final project reflect the passage's development of its themes?$q$, $q$[{"text":"Using only images of objects shows that she ignored Mr. Adeyemi's advice.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Moving from the empty basket to the index cards traces her own shift from seeing only loss to seeing what continues.","is_correct":true},{"text":"Starting with people and ending with the basket shows that loss wins in the end.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Hanging the project in May shows that the laundromat closed in the spring.","is_correct":false,"misconception_token":"off-topic"}]$q$::jsonb, $q$Moving from the empty basket to the index cards traces her own shift from seeing only loss to seeing what continues.$q$, $q$The project begins with the basket she once fixated on and ends with Mr. Adeyemi's cards, mirroring her change and the theme. The order runs from basket to cards, not the reverse.$q$, 'draft', '7aaa60c9-4dd2-53dd-94f3-8c7341e558e5')
