values
  ('c0535e60-fd08-5b19-b3a1-029a66117ad6', null, (select id from public.skills where slug = 'read-g12-word-parts'), null, 'hard',
   $q$"Omniscient" combines omni ("all") with sci, the root found in "science" and "conscious." What feeling did the platform give visitors?$q$, $q$[{"text":"A sense of knowing everything happening in a place","is_correct":true},{"text":"A sense of looking down from a great height","is_correct":false,"misconception_token":"context-only-guess"},{"text":"A sense of having power over the whole scene","is_correct":false,"misconception_token":"ignores-second-root"},{"text":"A sense of being present in every place at once","is_correct":false,"misconception_token":"confuses-similar-word"}]$q$::jsonb, $q$A sense of knowing everything happening in a place$q$, $q$Sci relates to knowing, so omniscient means all-knowing, and the passage adds "as if they could know everything happening in a place." Being present everywhere is the meaning of omnipresent, which shares only the prefix.$q$, 'draft', '451f4af7-ccaf-5ea7-9a85-5e91edabce6e')
